#[derive(Debug, Default, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RawConfig {
    database_url: Option<String>,
    secret_key_path: Option<String>,
    ipv6: Option<bool>,
    open_enrollment: Option<bool>,
    #[serde(default)]
    apns: RawApns,
    #[serde(default)]
    rate_limits: RawRateLimits,
}

